import test from "node:test";
import assert from "node:assert/strict";
import {
	closeStore,
	correct,
	deletedFacts,
	exportBundle,
	forget,
	getFact,
	getVersion,
	importBundle,
	listEntities,
	liveFacts,
	openStore,
	overview,
	remember,
	search,
} from "../lib/store.js";
import { OntologyError } from "../lib/store.js";

/** @returns {{store: any}} fresh in-memory store. */
function fresh() {
	return { store: openStore(":memory:") };
}

test("remember + duplicate suppression", () => {
	const { store } = fresh();
	try {
		const first = remember(store, { subject: "self", predicate: "name", object: "张三" });
		assert.equal(first.duplicate, false);
		assert.equal(first.fact.subject, "我");
		assert.equal(first.fact.pinned, true);
		const second = remember(store, { subject: "self", predicate: "name", object: "张三" });
		assert.equal(second.duplicate, true);
		assert.equal(second.fact.id, first.fact.id);
		assert.equal(overview(store).counts.facts, 1);
	} finally {
		closeStore(store);
	}
});

test("single-valued predicates supersede instead of contradicting", () => {
	const { store } = fresh();
	try {
		const old = remember(store, { subject: "self", predicate: "city", object: "上海" });
		const next = remember(store, { subject: "self", predicate: "city", object: "深圳" });
		assert.deepEqual(next.superseded, [old.fact.id]);
		const live = search(store, { predicate: "city" });
		assert.equal(live.length, 1);
		assert.equal(live[0].object, "深圳");
		const history = search(store, { predicate: "city", history: true });
		assert.equal(history.length, 2);
	} finally {
		closeStore(store);
	}
});

test("relation creates a person entity and keeps the role", () => {
	const { store } = fresh();
	try {
		const relation = remember(store, {
			subject: "self",
			predicate: "relation",
			object: "妈妈",
			qualifier: "mother",
		});
		assert.equal(relation.fact.object_kind, "entity");
		assert.equal(relation.fact.object, "妈妈");
		assert.equal(relation.fact.qualifier, "mother");
		const birthday = remember(store, { subject: "妈妈", predicate: "birthday", object: "1960-03-14" });
		assert.equal(birthday.fact.subject, "妈妈");
		const entities = listEntities(store);
		assert.equal(entities.find((entity) => entity.name === "妈妈").kind, "person");
	} finally {
		closeStore(store);
	}
});

test("correct retires the old object and keeps history", () => {
	const { store } = fresh();
	try {
		const first = remember(store, { subject: "self", predicate: "name", object: "张三" });
		const fixed = correct(store, { factId: first.fact.id, object: "李四" });
		assert.equal(fixed.fact.object, "李四");
		assert.equal(getFact(store, first.fact.id).object, "张三");
		const live = search(store, { predicate: "name" });
		assert.equal(live.length, 1);
		assert.equal(live[0].object, "李四");
	} finally {
		closeStore(store);
	}
});

test("soft forget hides the fact but keeps the row; hard delete removes it", () => {
	const { store } = fresh();
	try {
		const fact = remember(store, { subject: "self", predicate: "allergy", object: "花生" });
		const soft = forget(store, { factId: fact.fact.id });
		assert.equal(soft.count, 1);
		assert.equal(search(store, { query: "花生" }).length, 0);
		assert.equal(search(store, { query: "花生", history: true }).length, 1);
		const hard = forget(store, { factId: fact.fact.id, hard: true });
		assert.equal(hard.count, 1);
		assert.equal(search(store, { query: "花生", history: true }).length, 0);
	} finally {
		closeStore(store);
	}
});

test("the version bumps on every mutation, not on reads", () => {
	const { store } = fresh();
	try {
		assert.equal(getVersion(store), 0);
		remember(store, { subject: "self", predicate: "note", object: "x" });
		const version = getVersion(store);
		assert.ok(version > 0);
		search(store, {});
		assert.equal(getVersion(store), version);
	} finally {
		closeStore(store);
	}
});

test("unknown predicates and bad dates fail closed", () => {
	const { store } = fresh();
	try {
		assert.throws(
			() => remember(store, { subject: "self", predicate: "favoriteColor", object: "blue" }),
			(error) => error instanceof OntologyError && error.code === "UNKNOWN_PREDICATE",
		);
		assert.throws(
			() => remember(store, { subject: "self", predicate: "birthday", object: "next spring" }),
			(error) => error instanceof OntologyError && error.code === "BAD_INPUT",
		);
		assert.throws(
			() => remember(store, { subject: "self", predicate: "relation", object: "妈妈" }),
			(error) => error instanceof OntologyError && error.code === "BAD_INPUT",
		);
	} finally {
		closeStore(store);
	}
});

test("overview and liveFacts agree", () => {
	const { store } = fresh();
	try {
		remember(store, { subject: "self", predicate: "name", object: "张三" });
		remember(store, { subject: "self", predicate: "note", object: "喜欢徒步" });
		const summary = overview(store);
		assert.equal(summary.counts.facts, 2);
		assert.equal(summary.counts.pinned, 1);
		assert.equal(summary.pinned.length, 1);
		const all = liveFacts(store, 10);
		assert.equal(all.length, 2);
		assert.equal(all[0].pinned, true);
		assert.equal(all[0].object, "张三");
	} finally {
		closeStore(store);
	}
});

test("bundle export/import merges by identity and is idempotent", () => {
	const a = openStore(":memory:");
	const b = openStore(":memory:");
	try {
		remember(a, { subject: "self", predicate: "name", object: "张三" });
		remember(a, { subject: "self", predicate: "allergy", object: "花生" });
		remember(a, { subject: "self", predicate: "relation", object: "妈妈", qualifier: "mother" });
		remember(a, { subject: "妈妈", predicate: "birthday", object: "1960-03-14" });
		const bundle = exportBundle(a);
		assert.equal(bundle.format, "harmonygo-ontology-bundle");
		assert.equal(bundle.version, 1);
		assert.equal(bundle.entities.length, 2);
		assert.equal(bundle.facts.length, 4);

		const first = importBundle(b, bundle);
		assert.equal(first.imported, 4);
		assert.equal(first.entitiesCreated, 1);
		assert.equal(overview(b).counts.facts, 4);
		assert.equal(search(b, { query: "妈妈" }).length, 2);

		const again = importBundle(b, bundle);
		assert.equal(again.imported, 0);
		assert.equal(again.skipped, 4);
		assert.equal(overview(b).counts.facts, 4);
	} finally {
		closeStore(a);
		closeStore(b);
	}
});

test("single-valued merge lets the newer valid_from win", () => {
	const a = openStore(":memory:");
	const b = openStore(":memory:");
	try {
		remember(a, { subject: "self", predicate: "city", object: "上海" });
		const bundle = exportBundle(a);
		remember(b, { subject: "self", predicate: "city", object: "深圳" });
		const older = JSON.parse(JSON.stringify(bundle));
		older.facts[0].observed_at = "2000-01-01T00:00:00.000Z";
		older.facts[0].valid_from = "2000-01-01T00:00:00.000Z";
		older.facts[0].recorded_at = "2000-01-01T00:00:00.000Z";
		const oldOutcome = importBundle(b, older);
		assert.equal(oldOutcome.imported, 1);
		assert.equal(oldOutcome.historical, 1);
		assert.equal(search(b, { predicate: "city" })[0].object, "深圳");

		const newer = JSON.parse(JSON.stringify(bundle));
		newer.facts[0].observed_at = "2999-01-01T00:00:00.000Z";
		newer.facts[0].valid_from = "2999-01-01T00:00:00.000Z";
		newer.facts[0].recorded_at = "2999-01-01T00:00:00.000Z";
		const outcome = importBundle(b, newer);
		assert.equal(outcome.imported, 1);
		assert.equal(outcome.superseded, 1);
		assert.equal(search(b, { predicate: "city" })[0].object, "上海");
		assert.equal(search(b, { predicate: "city", history: true }).length, 3);
	} finally {
		closeStore(a);
		closeStore(b);
	}
});

test("deletions propagate through bundle tombstones", () => {
	const a = openStore(":memory:");
	const b = openStore(":memory:");
	try {
		const allergy = remember(a, { subject: "self", predicate: "allergy", object: "花生" });
		const bundle = exportBundle(a);
		importBundle(b, bundle);
		forget(a, { factId: allergy.fact.id });
		const afterDelete = exportBundle(a);
		assert.equal(afterDelete.facts.some((fact) => fact.predicate === "allergy"), false);
		const outcome = importBundle(b, afterDelete);
		assert.equal(outcome.retracted, 1);
		assert.equal(search(b, { query: "花生" }).length, 0);
	} finally {
		closeStore(a);
		closeStore(b);
	}
});

test("deletedFacts returns soft-deleted facts and excludes superseded ones", () => {
	const { store } = fresh();
	try {
		const allergy = remember(store, { subject: "self", predicate: "allergy", object: "花生" });
		remember(store, { subject: "self", predicate: "city", object: "上海" });
		const city = search(store, { predicate: "city" })[0];
		correct(store, { factId: city.id, object: "北京" });
		forget(store, { factId: allergy.fact.id });
		const deleted = deletedFacts(store);
		assert.equal(deleted.length, 1);
		assert.equal(deleted[0].object, "花生");
		assert.equal(deleted[0].retired_at.length > 0, true);
		assert.equal(search(store, { predicate: "city" })[0].object, "北京");
	} finally {
		closeStore(store);
	}
});

test("deletedFacts dedupes repeated deletions of the same fact", () => {
	const { store } = fresh();
	try {
		for (let i = 0; i < 2; i++) {
			const fact = remember(store, { subject: "self", predicate: "name", object: "林舟" });
			forget(store, { factId: fact.fact.id });
		}
		const deleted = deletedFacts(store);
		assert.equal(deleted.length, 1);
		assert.equal(deleted[0].object, "林舟");
	} finally {
		closeStore(store);
	}
});

test("bundle carries tombstones and import retires an older live fact", () => {
	const a = openStore(":memory:");
	const b = openStore(":memory:");
	try {
		const allergy = remember(a, { subject: "self", predicate: "allergy", object: "花生" });
		importBundle(b, exportBundle(a));
		assert.equal(search(b, { predicate: "allergy" }).length, 1);

		forget(a, { factId: allergy.fact.id });
		const bundle = exportBundle(a);
		assert.equal(bundle.facts.length, 0);
		assert.equal(bundle.tombstones.length, 1);
		assert.equal(bundle.tombstones[0].object, "花生");

		const outcome = importBundle(b, bundle);
		assert.equal(outcome.retracted, 1);
		assert.equal(search(b, { predicate: "allergy" }).length, 0);
		assert.equal(deletedFacts(b).length, 1);
	} finally {
		closeStore(a);
		closeStore(b);
	}
});

test("a newer live fact survives an older tombstone", () => {
	const a = openStore(":memory:");
	const b = openStore(":memory:");
	try {
		const allergy = remember(a, { subject: "self", predicate: "allergy", object: "花生" });
		forget(a, { factId: allergy.fact.id });
		const bundle = exportBundle(a);
		remember(b, { subject: "self", predicate: "allergy", object: "花生", observedAt: "2999-01-01T00:00:00.000Z" });
		const outcome = importBundle(b, bundle);
		assert.equal(outcome.retracted, 0);
		assert.equal(search(b, { predicate: "allergy" }).length, 1);
	} finally {
		closeStore(a);
		closeStore(b);
	}
});

test("a re-added fact newer than its tombstone survives a round trip", () => {
	const a = openStore(":memory:");
	const b = openStore(":memory:");
	try {
		const first = remember(a, { subject: "self", predicate: "allergy", object: "花生" });
		forget(a, { factId: first.fact.id });
		remember(a, { subject: "self", predicate: "allergy", object: "花生", observedAt: "2999-01-01T00:00:00.000Z" });
		const bundle = exportBundle(a);
		assert.equal(bundle.facts.length, 1);
		assert.equal(bundle.tombstones.length, 1);

		const outcome = importBundle(b, bundle);
		assert.equal(outcome.imported, 1);
		assert.equal(outcome.retracted, 0);
		assert.equal(search(b, { predicate: "allergy" }).length, 1);
	} finally {
		closeStore(a);
		closeStore(b);
	}
});

test("preserveNewer keeps a newer value when importing older history", () => {
	const { store } = fresh();
	try {
		remember(store, { subject: "self", predicate: "name", object: "新名字", observedAt: "2999-01-01T00:00:00.000Z" });
		const outcome = remember(store, {
			subject: "self", predicate: "name", object: "旧名字",
			observedAt: "2000-01-01T00:00:00.000Z", preserveNewer: true,
		});
		assert.equal(outcome.skipped, true);
		const live = search(store, { predicate: "name" });
		assert.equal(live.length, 1);
		assert.equal(live[0].object, "新名字");
	} finally {
		closeStore(store);
	}
});

test("later valid_from replaces the current value and closes the old interval", () => {
	const { store } = fresh();
	try {
		const old = remember(store, {
			subject: "self", predicate: "city", object: "上海",
			observedAt: "2020-01-01T00:00:00.000Z", validFrom: "2020-01-01T00:00:00.000Z",
		});
		const next = remember(store, {
			subject: "self", predicate: "city", object: "北京",
			observedAt: "2024-01-01T00:00:00.000Z", validFrom: "2024-01-01T00:00:00.000Z",
		});
		assert.equal(search(store, { predicate: "city" })[0].object, "北京");
		const closed = getFact(store, old.fact.id);
		assert.equal(closed.valid_to, "2024-01-01T00:00:00.000Z");
		assert.equal(closed.superseded_by, next.fact.id);
		assert.equal(typeof closed.superseded_at, "string");
		assert.equal(next.fact.valid_from, "2024-01-01T00:00:00.000Z");
		assert.equal(typeof next.fact.recorded_at, "string");
	} finally {
		closeStore(store);
	}
});

test("earlier valid_from is stored as history and does not replace the current value", () => {
	const { store } = fresh();
	try {
		const current = remember(store, {
			subject: "self", predicate: "city", object: "北京",
			observedAt: "2024-01-01T00:00:00.000Z", validFrom: "2024-01-01T00:00:00.000Z",
		});
		const historical = remember(store, {
			subject: "self", predicate: "city", object: "上海",
			observedAt: "2026-01-01T00:00:00.000Z", validFrom: "2020-01-01T00:00:00.000Z",
		});
		assert.equal(historical.historical, true);
		assert.equal(search(store, { predicate: "city" })[0].object, "北京");
		const closed = getFact(store, historical.fact.id);
		assert.equal(closed.valid_to, "2024-01-01T00:00:00.000Z");
		assert.equal(closed.superseded_by, current.fact.id);
		assert.equal(search(store, { predicate: "city", history: true }).length, 2);
	} finally {
		closeStore(store);
	}
});

test("correct closes the old interval at the new effective time", () => {
	const { store } = fresh();
	try {
		const old = remember(store, {
			subject: "self", predicate: "city", object: "上海",
			observedAt: "2020-01-01T00:00:00.000Z", validFrom: "2020-01-01T00:00:00.000Z",
		});
		correct(store, {
			factId: old.fact.id, object: "北京",
			effectiveAt: "2025-06-01T00:00:00.000Z",
		});
		assert.equal(search(store, { predicate: "city" })[0].object, "北京");
		const closed = getFact(store, old.fact.id);
		assert.equal(closed.valid_to, "2025-06-01T00:00:00.000Z");
		assert.equal(typeof closed.superseded_at, "string");
	} finally {
		closeStore(store);
	}
});
